import { useState, useEffect, useLayoutEffect, useRef, useMemo, Fragment } from "react";

(() => {
  // Inter from Google Fonts
  const l1 = document.createElement("link");
  l1.rel = "stylesheet";
  l1.href = "https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&family=Nunito:wght@400;500;600;700;800;900&family=Urbanist:wght@400;500;600;700;800&family=Quicksand:wght@500;600;700&family=Plus+Jakarta+Sans:wght@500;600;700;800&display=swap";
  document.head.appendChild(l1);
  // General Sans from Fontshare
  const l2 = document.createElement("link");
  l2.rel = "stylesheet";
  l2.href = "https://api.fontshare.com/v2/css?f[]=general-sans@500,600,700&display=swap";
  document.head.appendChild(l2);

  // ── PWA / "Add to Home Screen" — makes Luma launch FULLSCREEN as a real app
  //    (no Safari chrome, not a link back into Safari), with the Luma sun icon.
  //    Done here so it travels with this file; no separate index.html needed.
  const setMeta = (name, content, useProperty) => {
    const sel = useProperty ? `meta[property="${name}"]` : `meta[name="${name}"]`;
    let m = document.head.querySelector(sel);
    if (!m) { m = document.createElement("meta"); useProperty ? m.setAttribute("property", name) : m.setAttribute("name", name); document.head.appendChild(m); }
    m.setAttribute("content", content);
  };
  // Viewport: cover the notch/safe areas so fullscreen standalone fills the screen.
  // CRITICAL: Do NOT include `maximum-scale=1` or `user-scalable=no` here.
  // In iOS PWA standalone mode (apple-mobile-web-app-capable=yes), locking
  // zoom causes a well-documented WebKit bug where touch coordinates get
  // mapped to slightly the wrong screen position — taps register a few px
  // above where the finger actually lands, so users have to tap *below* a
  // button's visible bounds to trigger it. Allowing scale fixes the
  // misalignment without making the app actually zoomable (standalone PWAs
  // don't expose pinch-zoom by default).
  setMeta("viewport", "width=device-width, initial-scale=1, viewport-fit=cover");
  // iOS standalone: launch without Safari UI.
  setMeta("apple-mobile-web-app-capable", "yes");
  setMeta("mobile-web-app-capable", "yes");
  setMeta("apple-mobile-web-app-title", "Luma");
  setMeta("application-name", "Luma");
  // Status bar: "default" gives BLACK text on a LIGHT bar — needed because the
  // app's primary surface (home/header) is near-white. Previously this was
  // "black-translucent", which forces WHITE text — invisible against the white
  // Status bar style — MUST match the app theme, but NEVER use
  // "black-translucent". In standalone PWA, black-translucent makes the web
  // view extend full-screen *under* the status bar, which causes TWO bugs on
  // iPhone:
  //   (1) Touch hit-testing gets offset by the status-bar height, so taps
  //       land a few px ABOVE the visual target — the user has to press
  //       *below* a button to trigger it.
  //   (2) The translucent overlay lets the underlying view bleed through at
  //       the rounded-corner edges → a bright line on the side in dark mode.
  // "black" (dark) gives a solid black bar with white text that matches the
  // #0E0E10 app base with no seam, and keeps the web view in its normal
  // bounds so coordinates and edges are correct. "default" (light) gives a
  // black-on-light bar matching the near-white light theme.
  // Splash is always light (see below), so the boot status bar must be light
  // too — "default" gives dark text that stays readable on the cream splash.
  // The React app re-syncs this to the real theme once it mounts (so a dark
  // app still gets a dark bar after load).
  setMeta("apple-mobile-web-app-status-bar-style", "default");
  // Theme colour — paints the iOS PWA status-bar region. Must match the app
  // body to avoid a visible band where they meet.
  setMeta("theme-color", "#FBFDFE");

  // The Luma sun icon (home-screen app icon) — the warm peach/bronze pearl
  // the user chose. Scaled to sit within iOS's safe zone (motif ~75% of the
  // canvas) so it never crops against the rounded icon mask. Soft pearl
  // background with a gentle warm bloom rather than flat white.
  // ── Luma app icon — the "lu" mark: a tall left stroke (the l) flowing into a
  //    soft cup (the u), with the warm brand pearl resting in the bowl, on a
  //    warm cream rounded square. Geometry measured to match the brand sheet.
  //    Replaces the previous sun mark.
  const MARK_NAVY = "#1F1B2E";
  const ICON_SVG = `<svg xmlns="http://www.w3.org/2000/svg" width="512" height="512" viewBox="0 0 512 512">
    <defs>
      <radialGradient id="bg" cx="50%" cy="38%" r="80%">
        <stop offset="0%" stop-color="#FFFCF7"/>
        <stop offset="55%" stop-color="#FBF1E6"/>
        <stop offset="100%" stop-color="#F3E6D7"/>
      </radialGradient>
      <radialGradient id="pearl" cx="38%" cy="32%" r="72%">
        <stop offset="0%" stop-color="#FFFFFF"/>
        <stop offset="30%" stop-color="#FFF2E6"/>
        <stop offset="70%" stop-color="#F8D2B2"/>
        <stop offset="100%" stop-color="#EDB78F"/>
      </radialGradient>
      <radialGradient id="pearlGlow" cx="50%" cy="50%" r="50%">
        <stop offset="0%" stop-color="#F4A861" stop-opacity="0.55"/>
        <stop offset="45%" stop-color="#F0985A" stop-opacity="0.22"/>
        <stop offset="100%" stop-color="#F4A861" stop-opacity="0"/>
      </radialGradient>
    </defs>
    <rect width="512" height="512" rx="114" fill="url(#bg)"/>
    <path d="M176.6 107.5 L176.6 325.1 A79.4 79.4 0 0 0 335.4 325.1 L335.4 221.7" fill="none" stroke="${MARK_NAVY}" stroke-width="65.5" stroke-linecap="round" stroke-linejoin="round"/>
    <circle cx="256" cy="317.4" r="92" fill="url(#pearlGlow)"/>
    <circle cx="256" cy="317.4" r="35.8" fill="url(#pearl)"/>
    <circle cx="245.8" cy="307.2" r="11.3" fill="#FFFFFF" opacity="0.5"/>
  </svg>`;
  const iconUrl = "data:image/svg+xml;base64," + btoa(unescape(encodeURIComponent(ICON_SVG)));

  // Apple touch icon (home-screen icon on iOS).
  let ati = document.head.querySelector('link[rel="apple-touch-icon"]');
  if (!ati) { ati = document.createElement("link"); ati.rel = "apple-touch-icon"; document.head.appendChild(ati); }
  ati.setAttribute("href", iconUrl);
  let fav = document.head.querySelector('link[rel="icon"]');
  if (!fav) { fav = document.createElement("link"); fav.rel = "icon"; document.head.appendChild(fav); }
  fav.setAttribute("type", "image/svg+xml"); fav.setAttribute("href", iconUrl);

  // Web app manifest (Android/Chrome + general PWA) as a data-URI.
  // Read the user's stored theme preference so the manifest's background_color
  // matches it. iOS PWA standalone uses this colour to fill the safe-area
  // regions (notch, home-indicator) until the React app paints over them.
  // A wrong colour here is what creates the ugly "white frame" some users
  // were seeing along the screen edges in dark mode.
  let storedTheme = "light";
  try {
    const raw = typeof localStorage !== "undefined" ? localStorage.getItem("luma_v1_cfg") : null;
    if (raw) {
      const parsed = JSON.parse(raw);
      if (parsed && parsed.theme === "dark") storedTheme = "dark";
    }
  } catch (_) {}
  const manifestBg = storedTheme === "dark" ? "#0E0E10" : "#FBFDFE";

  // PAINT THE EDGES IMMEDIATELY — before React mounts.
  // Why: the safe-area zones (notch, home-indicator, and the slim 1–2px strip
  // iOS reserves on the left/right edges of devices with rounded corners) are
  // painted from `html`/`body` background, NOT from the React tree. If we wait
  // for React's first commit, those edges flash the browser default (white)
  // for a few frames in dark mode → reads as "bright frame on the sides of
  // the screen". Setting html.style.background here ensures the very first
  // pixel iOS paints already matches the theme.
  try {
    document.documentElement.style.background = manifestBg;
    document.documentElement.classList.add(storedTheme === "dark" ? "lt-theme-dark" : "lt-theme-light");
    if (document.body) document.body.style.background = manifestBg;
  } catch (_) {}
  // PRE-REACT BOOT OVERLAY — paints the Luma sun the very moment our JS runs.
  // Why: iOS caches the launch splash PNG aggressively. Even after we update
  // makeSplash (the ring-free design), iOS may keep showing the OLD cached
  // splash on startup until the PWA is reinstalled. By drawing the SAME sun
  // here, in pure HTML/SVG, before React mounts, we cover whatever iOS chose
  // to show — so the user always sees the new Luma sun. React's own boot
  // overlay then takes over seamlessly; this static one removes itself when
  // React mounts.
  try {
    var injectPreBoot = function(){
      if (!document.body || document.getElementById("lumaPreBoot")) return;
      // SPLASH IS ALWAYS LIGHT — never theme-aware. iOS was showing a stale
      // cached DARK launch image and then jumping to this overlay (the dark→
      // light flash). Locking every splash layer to the light cream look means
      // there is no dark splash variant in the code at all, for any theme.
      var sunFill = "#1F1B2E";
      var bg = "#FBFDFE";
      var pre = document.createElement("div");
      pre.id = "lumaPreBoot";
      pre.setAttribute("aria-hidden", "true");
      pre.style.cssText = "position:fixed;inset:0;z-index:2147483646;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:26px;background:"+bg+";opacity:1;pointer-events:none;overflow:hidden";
      var markStroke = "#1F1B2E";
      var icoBgA = "#FFFCF7";
      var icoBgB = "#F3E6D7";
      var ICON = 104;
      pre.innerHTML =
        '<style>'
        + '#lumaPreBoot *{backface-visibility:hidden;-webkit-backface-visibility:hidden}'
        + '@keyframes lumaPreBreath{0%,100%{transform:translateZ(0) scale(1)}50%{transform:translateZ(0) scale(1.018)}}'
        + '@keyframes lumaPreIconIn{0%{opacity:0;transform:translateZ(0) scale(0.94)}100%{opacity:1;transform:translateZ(0) scale(1)}}'
        + '.lpaura{position:absolute;left:50%;top:43%;width:340px;height:340px;border-radius:50%;background:radial-gradient(circle, rgba(232,168,120,0.14) 0%, rgba(232,168,120,0.05) 46%, rgba(232,168,120,0) 70%);transform:translate(-50%,-50%);pointer-events:none;z-index:0}'
        + '</style>'
        + '<div class="lpaura"></div>'
        + '<div style="position:relative;z-index:2;animation:lumaPreIconIn 0.6s cubic-bezier(0.22,1,0.36,1) both">'
        + '<div style="will-change:transform;animation:lumaPreBreath 4.4s ease-in-out 1.0s infinite">'
        + '<svg width="' + ICON + '" height="' + ICON + '" viewBox="0 0 100 100" style="display:block;overflow:visible;filter:drop-shadow(0 16px 34px rgba(80,70,95,0.20))">'
        + '<defs>'
        + '<linearGradient id="lumaPreIcoBg" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="' + icoBgA + '"/><stop offset="100%" stop-color="' + icoBgB + '"/></linearGradient>'
        + '<radialGradient id="lumaPrePearl" cx="38%" cy="32%" r="74%"><stop offset="0%" stop-color="#FFFFFF"/><stop offset="30%" stop-color="#FFF2E6"/><stop offset="70%" stop-color="#F8D2B2"/><stop offset="100%" stop-color="#EDB78F"/></radialGradient>'
        + '</defs>'
        + '<rect x="0" y="0" width="100" height="100" rx="22.37" fill="url(#lumaPreIcoBg)"/>'
        + '<path d="M34.5 21 L34.5 63.5 A15.5 15.5 0 0 0 65.5 63.5 L65.5 43.3" fill="none" stroke="' + markStroke + '" stroke-width="12.8" stroke-linecap="round"/>'
        + '<circle cx="50" cy="62" r="7" fill="url(#lumaPrePearl)"/>'
        + '<circle cx="48" cy="60" r="2.2" fill="#FFFFFF" opacity="0.5"/>'
        + '</svg>'
        + '</div>'
        + '</div>';
      document.body.appendChild(pre);
      // ── Single, smooth hand-off ────────────────────────────────────────
      // The pre-boot splash is the ONE AND ONLY splash. It removes itself the
      // moment BOTH are true: (1) the entrance animation has played at least
      // once (minShow), and (2) React has signalled it's mounted and painted
      // (window.__lumaReady). Then it fades out once, gracefully — no second
      // overlay, no competing timers, no animation restart.
      var bornAt = performance.now();
      var minShow = 1100;          // clean fade-in is seen, then we move on
      var fadeMs = 650;
      var removed = false;
      var fadeOut = function(){
        if (removed) return; removed = true;
        var el = document.getElementById("lumaPreBoot");
        if (!el) return;
        // Freeze every inner animation and clear will-change the instant we
        // begin to leave. Running keyframe loops + a simultaneous opacity
        // transition + live compositor layers is what caused the hitch on
        // mobile; once everything inside is static, the opacity fade is glass.
        var kids = el.querySelectorAll("*");
        for (var i=0;i<kids.length;i++){
          kids[i].style.animation = "none";
          kids[i].style.willChange = "auto";
        }
        // next frame: apply the fade (ensures the freeze has committed first)
        requestAnimationFrame(function(){
          el.style.transition = "opacity " + fadeMs + "ms ease";
          el.style.opacity = "0";
          setTimeout(function(){ el.parentNode && el.parentNode.removeChild(el); }, fadeMs + 60);
        });
      };
      var tryFinish = function(){
        var waited = performance.now() - bornAt;
        var ready = (typeof window !== "undefined") && window.__lumaReady;
        if (ready && waited >= minShow) { fadeOut(); return; }
        // poll until both conditions met, capped so we never hang on splash
        if (waited < 6000) { setTimeout(tryFinish, 60); }
        else fadeOut();   // safety: never trap the user on the splash
      };
      setTimeout(tryFinish, minShow);
    };
    if (document.body) injectPreBoot();
    else if (typeof document.addEventListener==="function") document.addEventListener("DOMContentLoaded", injectPreBoot, {once:true});
  } catch (_) {}
  const manifest = {
    name: "Luma", short_name: "Luma",
    description: "A schedule. A rhythm. A safety.",
    start_url: ".", scope: ".", display: "standalone", orientation: "any",
    background_color: manifestBg, theme_color: manifestBg,
    icons: [
      { src: iconUrl, sizes: "192x192", type: "image/svg+xml", purpose: "any" },
      { src: iconUrl, sizes: "512x512", type: "image/svg+xml", purpose: "any" },
      { src: iconUrl, sizes: "512x512", type: "image/svg+xml", purpose: "maskable" },
    ],
  };
  const manUrl = "data:application/manifest+json;base64," + btoa(unescape(encodeURIComponent(JSON.stringify(manifest))));
  let manLink = document.head.querySelector('link[rel="manifest"]');
  if (!manLink) { manLink = document.createElement("link"); manLink.rel = "manifest"; document.head.appendChild(manLink); }

  // ── iOS launch splash screens ─────────────────────────────────────────────
  // Without these, an iOS PWA shows a blank white flash before the React app
  // hydrates — feels broken, not like a native launch. iOS requires SEPARATE
  // images per device pixel-size and is strict about media-query matching:
  // the (device-width)/(device-height) MUST exactly match a real iPhone, or
  // iOS falls back to the blank screen. We generate each splash as a canvas
  // data-URI (same Luma sky + centered sun mark used for the icon), so no
  // external files are needed — the splashes travel with the bundle.
  const makeSplash = (w, h, dark, dpr) => {
    const c = document.createElement("canvas");
    c.width = w; c.height = h;
    const g = c.getContext("2d");
    // ALWAYS LIGHT — flat cream fill (#FBFDFE), identical to the pre-boot
    // overlay. The launch image is never dark, so the cached iOS launch image
    // can only ever be the light one once the PWA is reinstalled.
    g.fillStyle = "#FBFDFE";
    g.fillRect(0, 0, w, h);
    // Soft aura — IDENTICAL to the pre-boot overlay's .lpaura (a 340px CSS
    // circle centred at 50%/43%), so the static launch image and the live
    // overlay are pixel-aligned: no second, differently-sized splash.
    // The overlay is a full-screen fixed layer centred at 50% of the screen
    // (iOS standalone keeps the web view full-screen with the status bar drawn
    // on top), so the launch image's icon sits at the SAME 50% — no offset.
    var auraR = 170 * dpr;                          // 340px CSS diameter
    var aCx = w/2, aCy = h * 0.43;
    var ag = g.createRadialGradient(aCx, aCy, 0, aCx, aCy, auraR);
    ag.addColorStop(0, "rgba(232,168,120,0.14)");
    ag.addColorStop(0.46, "rgba(232,168,120,0.05)");
    ag.addColorStop(0.70, "rgba(232,168,120,0)");
    g.fillStyle = ag;
    g.beginPath(); g.arc(aCx, aCy, auraR, 0, Math.PI*2); g.fill();
    // NOTE: The app icon is intentionally NOT drawn into the launch image.
    // iOS bakes the launch image at install time and never refreshes it, so a
    // baked icon can drift out of level with the live overlay's icon across
    // versions/devices. By leaving the launch image as just the cream wash +
    // soft aura, there is no sharp element that can ever look "misaligned" —
    // the icon lives ONLY in the pre-boot overlay, where it fades in softly at
    // the true screen centre. The cream + aura are continuous between the
    // launch image and the overlay, so the hand-off reads as one calm surface.
    return c.toDataURL("image/png");
  };
  // Device size table — portrait orientation (iOS expects portrait splashes
  // for portrait launches). Devices are listed by logical CSS pixels with the
  // matching media-query device-width and -height. iOS picks the splash whose
  // media query matches the launching device.
  // Format: [cssWidth, cssHeight, devicePixelRatio]
  const SPLASH_DEVICES = [
    [430, 932, 3],   // iPhone 15 Pro Max, 14 Pro Max
    [428, 926, 3],   // iPhone 14 Plus, 13 Pro Max, 12 Pro Max
    [414, 896, 3],   // iPhone 11 Pro Max, XS Max
    [414, 896, 2],   // iPhone 11, XR
    [393, 852, 3],   // iPhone 15, 15 Pro, 14 Pro
    [390, 844, 3],   // iPhone 14, 13, 13 Pro, 12, 12 Pro
    [375, 812, 3],   // iPhone 13 mini, 12 mini, 11 Pro, X, XS
    [414, 736, 3],   // iPhone 8 Plus, 7 Plus, 6S Plus
    [375, 667, 2],   // iPhone SE 2/3, 8, 7, 6S, 6
    [320, 568, 2],   // iPhone SE 1
  ];
  // Generate splashes lazily — only those whose media query could match the
  // current device. This avoids burning CPU on splashes that will never load
  // (e.g. don't generate a 430x932 splash on a 320-wide iPhone SE).
  // For each matching device size we register ONE launch image, locked to the
  // app's stored theme (see below) — never a separate dark variant — so the
  // launch image can never disagree with the pre-boot overlay or the app base.
  const dw = window.screen.width, dh = window.screen.height;
  SPLASH_DEVICES.forEach(([cw, ch, dpr]) => {
    // Only generate if this device size could plausibly match (within a tier)
    const dev = Math.min(cw, dw)/Math.max(cw, dw);
    if (dev < 0.85 && !(cw === dw && ch === dh)) return; // skip wildly mismatched
    const px = cw * dpr, py = ch * dpr;
    // ALWAYS register the LIGHT launch image, regardless of app theme or the
    // device's system colour scheme. A dark launch image on a dark-system phone
    // (then jumping to the light app) was the dark→light flash. Light-only =
    // one consistent splash for everyone.
    const splashDark = false;
    const dataUrl = makeSplash(px, py, splashDark, dpr);
    const link = document.createElement("link");
    link.rel = "apple-touch-startup-image";
    link.media = `(device-width: ${cw}px) and (device-height: ${ch}px) and (-webkit-device-pixel-ratio: ${dpr}) and (orientation: portrait)`;
    link.href = dataUrl;
    document.head.appendChild(link);
  });
  manLink.setAttribute("href", manUrl);
})();

/* ══ Per-screen pastel palette (light & premium) ══ */
const SCREENS = {
  home:    { h:"#86B6D4", hl:"#EAF1F7", hll:"#F8FBFD", hb:"#FBFDFE", soft:"#C3D6E4", deep:"#557E9E" },
  timer:   { h:"#E89B89", hl:"#FBEDE7", hll:"#FEF7F3", hb:"#FEF7F2", soft:"#F5CDBC", deep:"#B36B57" },
  emotion: { h:"#B89DC4", hl:"#F2EBF6", hll:"#FAF7FC", hb:"#F8F4FB", soft:"#D5C5DD", deep:"#7B5D8C" },
  // comm/Tala — was a cool steel-blue that read too similar to the week
  // screen. Shifted toward a warmer dusty mineral-blue with a hint of green
  // undertone, so it sits between aqua-home and cool-week without competing
  // with either.
  comm:    { h:"#8FB8B2", hl:"#EBF3F1", hll:"#F6FAF9", hb:"#F2F8F6", soft:"#BBD3CD", deep:"#557D78" },
  // stories — was a dull yellow-beige (#C9A875). Shifted to a soft peach-rose
  // so the screen feels warmer and more storybook-romantic. Differentiated
  // from timer's brighter peach (#E89B89) by being slightly more muted and
  // pinker — a gentler, story-time hue.
  stories: { h:"#E2A088", hl:"#FAEDE6", hll:"#FDF7F3", hb:"#FCF4EE", soft:"#EDC4B3", deep:"#A66B55" },
  calm:    { h:"#A8C9B0", hl:"#EFF5F0", hll:"#F8FBF8", hb:"#F4F9F4", soft:"#CFDED2", deep:"#688D72" },
  idcard:  { h:"#D88B8B", hl:"#FAEAEA", hll:"#FDF5F5", hb:"#FCF3F3", soft:"#EDB8B8", deep:"#A35858" },
  tools:   { h:"#D9886B", hl:"#F8ECE5", hll:"#FCF7F3", hb:"#FBF5EE", soft:"#EDC1AE", deep:"#A2604A" },
  // week — same clean sky-blue family as home (~204°) but a step darker
  // (lightness ~58% vs home's 65%), so it shares home's bright white header
  // style yet reads as a slightly deeper, calmer blue of its own.
  week:    { h:"#7EB2D6", hl:"#E7EFF6", hll:"#F5F9FC", hb:"#F0F6FB", soft:"#BBD2E2", deep:"#4A7396" },
};
// Dark-mode screen palettes: keep each screen's accent identity (h/deep), but
// give it a deep night base + dark tints. Built once from SCREENS so the per-
// screen colour still tints the header glow, just over a dark canvas.
const SCREENS_DARK=Object.fromEntries(Object.entries(SCREENS).map(([k,v])=>[k,{
  h:v.h, deep:v.deep, soft:v.h,
  hb:"#100D1A",                                   // page base (matches editor ED.bg0)
  hl:"rgba(255,255,255,0.05)",                    // card/tint surface
  hll:"rgba(255,255,255,0.03)",                   // faint surface
}]));
// Resolve a screen's palette for the active theme.
const scrPal=(name)=>(APP_THEME==="dark"?SCREENS_DARK:SCREENS)[name]||(APP_THEME==="dark"?SCREENS_DARK:SCREENS).home;

/* Bottom-nav active-bubble pastels — a curated, HARMONIOUS progression in the
   nav order (home → idcard). Hues step gently from soft blue through violet,
   orchid, rose and into peach, so neighbouring tabs stay close and the bar
   reads as one soft pastel arc rather than clashing identity colours. These
   are intentionally NOT the (dynamic) per-page accents. Used in LIGHT mode;
   in DARK mode the active capsule is a colourless frosted "liquid glass". */
const NAV_PASTEL={
  home:   "#A8C8E8",
  week:   "#AFBFE6",
  timer:  "#BBB4E2",
  stories:"#CBB2DF",
  emotion:"#DAB4DB",
  calm:   "#E3B6CC",
  comm:   "#EBBBBA",
  idcard: "#EEC6AC",
};

const G = {
  ink:"#1F1B2E", ink2:"#6E6882", ink3:"#7C7691",
  // inkSoft — used for large display headings (h1/h2) so screen titles don't
  // feel heavy on a calm app. Hue stays in the same aubergine family as ink,
  // but lifted enough that pure-black weight is gone. Tested for WCAG AAA
  // contrast on white (~6.8:1) so headings remain readable for low-vision
  // users while losing the heavy "shouting" feel at full ink strength.
  inkSoft:"#524D6B",
  white:"#FFFFFF", cream:"#FCFBFE", border:"#EEEAF5", border2:"#E0DBEF",
  font:"'Urbanist','Nunito',system-ui,sans-serif",
  // Plus Jakarta Sans — modern humanist sans with gently rounded forms and a
  // premium, refined feel. Slightly softer and more characterful than Inter,
  // less juvenile than a fully rounded display face. Used for all headings;
  // pair with Inter (G.font) for body. Heading weights use 700–800 for presence.
  // Loaded via the Google Fonts <link> at the top of the file.
  serif:"'Plus Jakarta Sans','Nunito','Inter',system-ui,sans-serif",
};

/* ═══ Editor theme (ED) ═══
   A mature, atmospheric DARK palette used ONLY by the editors (the adult /
   pedagogue side). The user-facing app stays warm & light; the editor feels
   like a calm professional tool at night — matte dark base, faint stars, a
   soft glow in the active colour. Headings use the app's own Nunito (G.serif)
   and body uses Inter (G.font) so it lines up with the rest of Luma. */
const ED={
  bg0:"#100D1A", bg1:"#16131F", bg2:"#1E1A2C",
  text:"#F4F1FA", text2:"#A39EB5", text3:"#8E889E", text4:"#7E7891", text5:"#5C566E",
  cardBg:"rgba(255,255,255,0.045)", cardBg2:"rgba(255,255,255,0.07)",
  cardBorder:"rgba(255,255,255,0.075)", cardBorderHi:"rgba(255,255,255,0.11)",
  inset:"rgba(0,0,0,0.28)", insetBorder:"rgba(255,255,255,0.07)",
  hairline:"rgba(255,255,255,0.08)",
  // soft glow helpers from an accent hex
  glow:(hex,a=0.45)=>{const n=parseInt(hex.slice(1),16);return `rgba(${(n>>16)&255},${(n>>8)&255},${n&255},${a})`;},
};
/* ═══ Editor theme — LIGHT (EL) ═══
   The light-mode editor: a calm blue-harmonic backdrop toward the lighter end,
   keeping the same structure as the dark editor but bright and airy. Mirrors
   every ED key so the editor can swap palettes with one resolver. */
const EL={
  bg0:"#EAF0FA", bg1:"#F2F6FC", bg2:"#F7FAFE",
  text:"#23304A", text2:"#5A6B86", text3:"#7C8AA3", text4:"#94A0B6", text5:"#AEB8CB",
  cardBg:"rgba(255,255,255,0.72)", cardBg2:"rgba(255,255,255,0.55)",
  cardBorder:"rgba(60,90,140,0.12)", cardBorderHi:"rgba(60,90,140,0.2)",
  inset:"rgba(255,255,255,0.7)", insetBorder:"rgba(60,90,140,0.14)",
  hairline:"rgba(60,90,140,0.1)",
  glow:(hex,a=0.4)=>{const n=parseInt(hex.slice(1),16);return `rgba(${(n>>16)&255},${(n>>8)&255},${n&255},${a})`;},
};
// Resolve the editor palette for the active theme
const edPal=()=>isDark()?ED:EL;
// Active theme, set by App on each render from cfg.theme. Readable by any
// component during the render pass (App re-renders cascade to all children).
let APP_THEME="light";
const isDark=()=>APP_THEME==="dark";
// Global theme tokens — adaptive ink & surfaces for the whole app. In light
// mode these match the original warm palette; in dark mode they map to the
// night palette so every screen, card, header and tool can read one source.
const tk=()=>isDark()?{
  ink:"#F4F1FA", ink2:"#A39EB5", ink3:"#8E889E", inkSoft:"#EDEAF6",
  white:"rgba(255,255,255,0.05)", cream:"rgba(255,255,255,0.035)",
  border:"rgba(255,255,255,0.09)", border2:"rgba(255,255,255,0.13)",
  card:"rgba(255,255,255,0.05)", cardBorder:"rgba(255,255,255,0.08)",
  page:"#100D1A",
}:{
  ink:G.ink, ink2:G.ink2, ink3:G.ink3, inkSoft:G.inkSoft,
  white:G.white, cream:G.cream, border:G.border, border2:G.border2,
  card:G.white, cardBorder:G.border, page:"#FBFDFE",
};
// Collision-proof unique id. Date.now() alone can produce duplicate ids when
// two items are created within the same millisecond (e.g. a template that adds
// several activities at once, or quick taps). Because activity ids are used
// BOTH as React keys AND as the key into per-day done-state, a duplicate id
// makes the trash delete the wrong card and React render two cards with the
// same key — the "ghost / doubled card" seen in card view. Ids are only ever
// compared by equality (find/filter/=== and React keys), never used in
// arithmetic, and other entities in this app already use string ids ("s"+...,
// "c_"+...). So we return a guaranteed-unique string: timestamp + a monotonic
// counter that resets each millisecond.
let __uidLast=0, __uidSeq=0;
function uid(prefix="a"){
  const now=Date.now();
  if(now===__uidLast){ __uidSeq++; } else { __uidLast=now; __uidSeq=0; }
  return `${prefix}_${now}_${__uidSeq}`;
}
// When a confirmation dialog (e.g. "Discard changes?") opens on top of an
// editor sheet, scroll the editor back to its top first. Otherwise the
// dialog can pop up while the editor is scrolled deep down, making the
// dialog feel disconnected from any visible context. Picks the LAST (= top-
// most) visible [data-modal-scroll] in the DOM, since later modals stack
// above earlier ones.
function scrollActiveSheetToTop(){
  try{
    const all=document.querySelectorAll("[data-modal-scroll]");
    for(let i=all.length-1;i>=0;i--){
      const el=all[i];
      if(el.scrollTop>0){
        el.scrollTo({top:0,behavior:"smooth"});
        return;
      }
    }
  }catch(_){/* defensive: never break a save flow over scroll */}
}
// HSL→hex for the free color spectrum rail in editors
function hslToHex(h,s,l){h/=360;const a=s*Math.min(l,1-l);const f=n=>{const k=(n+h*12)%12;const c=l-a*Math.max(-1,Math.min(k-3,9-k,1));return Math.round(255*c).toString(16).padStart(2,"0");};return `#${f(0)}${f(8)}${f(4)}`;}
// Map a hex colour to its hue (0-360) so the spectrum rail knob can show position
function hexToHue(hex){if(!hex||hex.length<7)return 0;const r=parseInt(hex.slice(1,3),16)/255,g=parseInt(hex.slice(3,5),16)/255,b=parseInt(hex.slice(5,7),16)/255;const mx=Math.max(r,g,b),mn=Math.min(r,g,b),d=mx-mn;if(d===0)return 0;let h;if(mx===r)h=((g-b)/d)%6;else if(mx===g)h=(b-r)/d+2;else h=(r-g)/d+4;h*=60;return h<0?h+360:h;}

/* ═══ ColorField — unified colour picker used EVERYWHERE in the app ═══
   Spectrum drag-rail is the default (premium "glass-capsule" marker, concept B);
   a small pill toggle switches to fixed swatches. One component, one behaviour,
   everywhere: timer colour, activity colour, emotions, categories, week days,
   Sigvard lamp, now-line, story colours, etc.
   Props:
     value      current hex
     onChange   (hex) => void
     swatches   array of fixed hex options (shown in "Colours" mode)
     dark       force dark styling (else auto via isDark())
     sat,lig    HSL saturation/lightness for the rail (defaults tuned for calm)
═══ */
function ColorField({value,onChange,swatches=[],dark,sat=0.62,lig=0.6,lang="sv"}){
  const dk=dark===undefined?isDark():dark;
  const [mode,setMode]=useState("rail"); // spectrum first by default
  const railRef=useRef(null), knobRef=useRef(null);
  const onDown=e=>{
    e.preventDefault();e.stopPropagation();
    const rail=railRef.current,knob=knobRef.current;if(!rail)return;
    try{rail.setPointerCapture(e.pointerId);}catch(_){}
    const move=cx=>{
      const r=rail.getBoundingClientRect();
      let p=(cx-r.left)/r.width;p=p<0?0:p>1?1:p;
      if(knob)knob.style.left=`${p*100}%`;
      rail._hex=hslToHex(p*360,sat,lig);
    };
    move(e.clientX);
    const mv=ev=>{ev.preventDefault();move(ev.clientX);};
    const up=()=>{rail.removeEventListener("pointermove",mv);rail.removeEventListener("pointerup",up);rail.removeEventListener("pointercancel",up);if(rail._hex)onChange(rail._hex);};
    rail.addEventListener("pointermove",mv);rail.addEventListener("pointerup",up);rail.addEventListener("pointercancel",up);
  };
  return(
    <div>
      <div style={{display:"flex",justifyContent:"flex-end",marginBottom:10}}>
        <div style={{display:"flex",gap:3,padding:3,borderRadius:11,background:dk?"rgba(0,0,0,0.22)":"rgba(31,27,46,0.05)",border:dk?"1px solid rgba(255,255,255,0.06)":"none"}}>
          {[["rail",lang==="sv"?"Spektrum":"Spectrum"],["swatch",lang==="sv"?"Färger":"Colours"]].map(([k,lb])=>{
            const on=mode===k;
            return <button key={k} type="button" onClick={()=>setMode(k)} style={{padding:"5px 12px",borderRadius:8,border:"none",cursor:"pointer",fontFamily:G.font,fontWeight:600,fontSize:11,letterSpacing:.2,
              background:on?(dk?"rgba(255,255,255,0.14)":"#FFFFFF"):"transparent",
              color:on?(dk?"#F4F1FA":"#3A3550"):(dk?"#9E98AE":"#8E889E"),
              boxShadow:on&&!dk?"0 1px 3px rgba(31,27,46,0.1)":on&&dk?"inset 0 1px 0 rgba(255,255,255,0.2)":"none",
              transition:"all .2s ease"}}>{lb}</button>;
          })}
        </div>
      </div>
      {mode==="rail"?(
        <div style={{padding:"6px 6px 2px"}}>
          {/* generous hit area; the slim rounded rainbow strip is centred */}
          <div ref={railRef} onPointerDown={onDown}
            style={{position:"relative",height:32,display:"flex",alignItems:"center",cursor:"pointer",touchAction:"none",userSelect:"none",WebkitUserSelect:"none"}}>
            {/* slim premium rainbow strip — rounded ends (concept "B · Smal kapsel") */}
            <div style={{position:"absolute",left:0,right:0,top:"50%",transform:"translateY(-50%)",height:16,borderRadius:8,
              background:"linear-gradient(90deg, hsl(0,65%,60%), hsl(45,65%,60%), hsl(90,65%,60%), hsl(150,65%,60%), hsl(200,65%,60%), hsl(260,65%,60%), hsl(320,65%,60%), hsl(360,65%,60%))",
              boxShadow:dk?"inset 0 1px 3px rgba(0,0,0,0.4)":"inset 0 1px 3px rgba(31,27,46,0.18)"}}/>
            {/* slim glass capsule marker with a hairline inside */}
            <div ref={knobRef} style={{position:"absolute",top:"50%",left:`${(hexToHue(value)/360)*100}%`,transform:"translate(-50%,-50%)",width:11,height:30,borderRadius:6,
              background:"rgba(255,255,255,0.14)",backdropFilter:"blur(10px)",WebkitBackdropFilter:"blur(10px)",
              border:"1px solid rgba(255,255,255,0.7)",boxShadow:"0 3px 9px rgba(0,0,0,0.3), inset 0 1px 0 rgba(255,255,255,0.6)",
              pointerEvents:"none",display:"flex",alignItems:"center",justifyContent:"center"}}>
              <div style={{width:1,height:14,background:"#fff",borderRadius:1,opacity:0.95}}/>
            </div>
          </div>
          <div style={{fontFamily:G.font,fontSize:11,color:dk?"#8E889E":"#9A93AB",marginTop:11,textAlign:"center"}}>{lang==="sv"?"Dra för att välja färg":"Drag to choose a colour"}</div>
        </div>
      ):(
        <div style={{display:"flex",gap:10,flexWrap:"wrap"}}>
          {swatches.map(col=>{
            const selChk=col==="#FFFFFF";
            const sel=value===col;
            return(
              <div key={col} onClick={()=>onChange(col)} className="lt-press-soft" style={{
                width:36,height:36,borderRadius:"50%",background:col,cursor:"pointer",position:"relative",
                transform:sel?"scale(1.1)":"scale(1)",
                border:selChk?"1px solid #E0DBEF":"none",
                boxShadow:sel?`0 0 0 3px ${dk?"#15131F":"#fff"}, 0 0 0 5px ${selChk?"#C9C4D8":col}, 0 8px 20px ${selChk?"rgba(31,27,46,0.18)":`${col}55`}`:`0 2px 6px ${selChk?"rgba(31,27,46,0.12)":`${col}33`}`,
                transition:"transform .25s cubic-bezier(0.34, 1.56, 0.64, 1), box-shadow .25s ease",
              }}>
                {sel&&<svg viewBox="0 0 24 24" fill="none" stroke={selChk?"#1F1B2E":"#FFFFFF"} strokeWidth="3" strokeLinecap="round" strokeLinejoin="round" style={{position:"absolute",inset:0,width:"100%",height:"100%",padding:8}}><path d="M5 12l5 5L20 7"/></svg>}
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}

const sh = {
  xs:"0 1px 2px rgba(31,27,46,0.04), 0 1px 1px rgba(31,27,46,0.03)",
  sm:"0 1px 3px rgba(31,27,46,0.04), 0 4px 12px rgba(31,27,46,0.05)",
  md:"0 2px 6px rgba(31,27,46,0.04), 0 12px 30px rgba(31,27,46,0.09), 0 4px 10px rgba(31,27,46,0.04)",
  lg:"0 4px 12px rgba(31,27,46,0.06), 0 24px 60px rgba(31,27,46,0.12), 0 8px 20px rgba(31,27,46,0.06)",
  c: col=>`0 2px 5px ${col}1A, 0 10px 26px ${col}3D, 0 4px 10px ${col}22`,
};

/* ═══════════════════════════════════════════════════════════════════════
   DESIGN SYSTEM TOKENS
   These are intentionally NEW and used in NEW code. Legacy callsites
   can migrate incrementally — both can coexist until the migration completes.
═══════════════════════════════════════════════════════════════════════ */

// Type scale — modular, 6 sizes. Each value pairs with its conventional
// letter-spacing so headings feel composed instead of hand-tuned per spot.
const TYPO = {
  caption:  { size: 11, tracking:  0.4, weight: 500 },  // aria-style, uppercase labels with caps tracking
  small:    { size: 12, tracking:  0.1, weight: 500 },  // helper text, hints
  body:     { size: 14, tracking:  0.1, weight: 500 },  // default UI text
  bodyLg:   { size: 16, tracking:  0,   weight: 500 },  // inputs, primary buttons
  h3:       { size: 18, tracking: -0.2, weight: 600 },  // tile titles, section headers in cards
  h2:       { size: 22, tracking: -0.3, weight: 500 },  // sub-screen headings (serif)
  h1:       { size: 28, tracking: -0.5, weight: 500 },  // screen titles (serif)
};

// Spacing grid — strict 4px multiples. Use these for paddings, gaps, margins.
// Discourages the 7/11/13/22 fractional values that have crept in over time.
const SPACE = { xs:4, sm:8, md:12, lg:16, xl:20, xxl:24, x3:32, x4:40, x5:48 };

/* ═══════════════════════════════════════════════════════════════════════
   ICON COMPONENTS — shared SVG vocabulary
   All UI icons (not content emoji) come from here. One source of truth for
   each glyph, plus consistent stroke, line-cap and joining behaviour.
═══════════════════════════════════════════════════════════════════════ */

// Pencil — used on every edit affordance. Animates via .lumaPen class when
// wrapped in a .lumaPenBtn parent (hover/press tilts the tip toward writing).
const IconPencil = ({size=16, className="lumaPen"})=>(
  <svg className={className} width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.9" strokeLinecap="round" strokeLinejoin="round">
    <path d="M11 4 H4 a2 2 0 0 0 -2 2 v14 a2 2 0 0 0 2 2 h14 a2 2 0 0 0 2 -2 v-7"/>
    <path d="M18.5 2.5 a2.121 2.121 0 0 1 3 3 L12 15 l-4 1 1 -4 z"/>
  </svg>
);

// Trash — destructive action across editors. Stroke matches pencil weight.
const IconTrash = ({size=16})=>(
  <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.9" strokeLinecap="round" strokeLinejoin="round">
    <path d="M3 6 h18"/>
    <path d="M8 6 V4 a2 2 0 0 1 2-2 h4 a2 2 0 0 1 2 2 v2"/>
    <path d="M19 6 l-1 14 a2 2 0 0 1 -2 2 H8 a2 2 0 0 1 -2 -2 L5 6"/>
    <line x1="10" y1="11" x2="10" y2="17"/>
    <line x1="14" y1="11" x2="14" y2="17"/>
  </svg>
);

// X — close/cancel affordance. Slightly thicker stroke (2.2) for visibility at small sizes.
const IconX = ({size=14, strokeWidth=2.2})=>(
  <svg width={size} height={size} viewBox="0 0 14 14" fill="none" stroke="currentColor" strokeWidth={strokeWidth} strokeLinecap="round">
    <path d="M3 3 L11 11 M11 3 L3 11"/>
  </svg>
);

// Check — save confirmation, "done" markers. Has the .saveTick class so the
// stroke animates when first rendered (drawn in, then springs on hover).
const IconCheck = ({size=15, className="saveTick", strokeWidth=2.4})=>(
  <svg className={className} width={size} height={size} viewBox="0 0 14 14" fill="none" stroke="currentColor" strokeWidth={strokeWidth} strokeLinecap="round" strokeLinejoin="round">
    <path d="M2.5 7.2 L5.8 10.5 L11.5 3.5"/>
  </svg>
);

// Chevron — directional navigation (next/prev, drilldown).
const IconChevron = ({dir="right", size=14, strokeWidth=2.2})=>{
  const points = dir==="left" ? "15 18 9 12 15 6"
              : dir==="right" ? "9 18 15 12 9 6"
              : dir==="up"    ? "18 15 12 9 6 15"
              : "6 9 12 15 18 9"; // down
  return(
    <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={strokeWidth} strokeLinecap="round" strokeLinejoin="round">
      <polyline points={points}/>
    </svg>
  );
};

// Camera — photo upload affordances. Used across editors (activity, emotion,
